template:
---
params { s: iri }
# a note about s
---
SELECT * WHERE { ?x a ${s} }

---
params {
  who: pname  # the subject
}
---
PREFIX ex: <http://example.org/>
SELECT * WHERE { ?s a ${who} }

---
params { classes: iri[] }
example demo "a#b" {
  classes: []
}
---
{% for c in classes %}${c}{% endfor %}

---
params {
  u: {
    id:   iri     # stable identifier
    name: string  # display name
  }
}
---
PREFIX ex: <http://example.org/>
SELECT * WHERE { ${u.id} ex:name ${u.name} }

---
params { classes: pname[] }
example demo {
  classes: [
    foaf:Person,       # people
    foaf:Organization  # and organizations
  ]
}
---
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT * WHERE { ?s a ?t . VALUES ?t { ${...classes} } }

---
params { u: { id: iri, name: string } }
example demo {
  u: { id: <http://example.org/1>,   # the id
       name: "Alice" }               # and the name
}
---
PREFIX ex: <http://example.org/>
SELECT * WHERE { ${u.id} ex:name ${u.name} }
